-- 006: final service text from the company + a short summary for cards. Run after 005.
alter table public.services add column if not exists short_description text;

on conflict (slug) do update set title=excluded.title, icon=excluded.icon, description=excluded.description,
  short_description=excluded.short_description, benefits=excluded.benefits, sort_order=excluded.sort_order;
-- image_path is NOT touched, so uploaded service pictures are kept.
